/**
 * 3D Blue noise generator using Hilbert curve and R1 sequence.
 * Produces high-quality low-discrepancy samples in 3D space.
 *
 * **Use Cases:**
 * - Volume sampling
 * - 3D dithering
 * - Particle distribution
 * - Stochastic volumetric rendering
 *
 * @function blueNoise3D
 * @param {Node.<ivec3>} p - 3D integer coordinates
 * @param {Node.<int>} level - Hilbert curve recursion level (4-6 recommended)
 * @returns {Node.<float>} Normalized blue noise value in [0..1]
 */
export const blueNoise3D: any;
/**
 * Trilinear interpolation for 3D texture sampling.
 * Smoothly interpolates signed distance values across voxel boundaries.
 *
 * @function trilinearSample
 * @param {Node} sdfTexture - 3D SDF texture (texture_3d<f32>)
 * @param {Node} sdfSampler - Texture sampler
 * @param {Node.<vec3>} uvw - Normalized texture coordinates [0..1]
 * @returns {Node.<float>} Interpolated SDF value
 */
export const trilinearSample: any;
/**
 * Computes the gradient (normal) of the SDF using central differences.
 * The gradient points in the direction of increasing distance (outward from surface).
 *
 * @function sdfGradient
 * @param {Node} sdfTexture - 3D SDF texture
 * @param {Node} sdfSampler - Texture sampler
 * @param {Node.<vec3>} uvw - Normalized texture coordinates
 * @param {Node.<vec3>} texelSize - Size of one texel in UV space (1/resolution)
 * @returns {Node.<vec3>} Normalized gradient vector (surface normal)
 */
export const sdfGradient: any;
/**
 * Transforms a world-space position to SDF texture coordinates.
 *
 * @function worldToSDFCoords
 * @param {Node.<vec3>} worldPos - World space position
 * @param {Node.<mat4>} inverseBoundsMatrix - Inverse of SDF bounds transformation
 * @returns {Node.<vec3>} SDF texture coordinates [0..1]
 */
export const worldToSDFCoords: any;
/**
 * Transforms SDF texture coordinates to world-space position.
 *
 * @function sdfCoordsToWorld
 * @param {Node.<vec3>} uvw - SDF texture coordinates [0..1]
 * @param {Node.<mat4>} boundsMatrix - SDF bounds transformation matrix
 * @returns {Node.<vec3>} World space position
 */
export const sdfCoordsToWorld: any;
/**
 * Boundary collision response for particles against SDF volume.
 * Applies penalty force when particle is outside the boundary (sdf > 0).
 *
 * @function sdfBoundaryResponse
 * @param {Node.<vec3>} position - Particle position
 * @param {Node.<vec3>} velocity - Particle velocity
 * @param {Node.<float>} sdfValue - Signed distance at particle position
 * @param {Node.<vec3>} sdfNormal - Surface normal from SDF gradient
 * @param {Node.<float>} stiffness - Boundary stiffness coefficient
 * @param {Node.<float>} damping - Velocity damping factor
 * @returns {Node.<vec4>} Updated (position.xyz, velocity.x) - use .xyz for pos, need to call again for full velocity
 */
export const sdfBoundaryResponse: any;
/**
 * Checks if a position is inside the SDF volume.
 *
 * @function isInsideSDF
 * @param {Node.<float>} sdfValue - Signed distance value
 * @param {Node.<float>} threshold - Distance threshold (typically 0.0)
 * @returns {Node.<bool>} True if inside volume (sdf < threshold)
 */
export const isInsideSDF: any;
